def merge(lst, incoming):
    by_id = {x['id']: x for x in lst}
    for x in incoming:
        by_id[x['id']] = {**by_id.get(x['id'], {}), **x}
    return sorted(by_id.values(), key=lambda x: -x['at'])
inbox = [{'id':'n1','at':100,'read':True}, {'id':'n2','at':200,'read':False}]
from_push = [{'id':'n3','at':300,'read':False}]
from_api  = [{'id':'n3','at':300,'read':False}, {'id':'n2','at':200,'read':True}]
inbox = merge(merge(inbox, from_push), from_api)
print(' | '.join(f"{x['id']} {'읽음' if x['read'] else '안읽음'}" for x in inbox))
print('안 읽은 수:', sum(not x['read'] for x in inbox))
